import React from "react";
import LoginLayout from "./LoginLayout";
import {forgetPassword} from "../services/AuthApi";
import {useNavigate} from "react-router-dom";

export default function ForgetPassword() {
    const navigate = useNavigate();

    function handleSubmit(user) {
        forgetPassword(user.username)
            .then(() => {
                alert('Password recovery email has been sent to your email');
                navigate("/");
            })
            .catch((e) => {
                if (e.response && e.response.data && e.response.data.error) {
                    alert(e.response.data.error); // in ra "User not found!"
                } else {
                    alert('Something went wrong!');
                }
            });
    }

    return (
        <LoginLayout
            title={`Forget Password`}
            handleOnSubmit={handleSubmit}
            linkHref={`/signup`}
            submitText={`Password Recovery`}
            label={`Sign up`}
            flag={false}
            linkHref2={'/'}
            label2={'Sign In'}
        />
    );
}
